/**
 * lib/python/repr.mjs
 *
 * Python's `repr()` for text, reproduced exactly.
 *
 * `jsonschema` interpolates the offending type name into its error message with
 * `{!r}`, so `Type 'foo' is unknown to this type checker` is really
 * `"Type %s is unknown ..." % repr(type)`.  Getting the quoting and escaping
 * right therefore matters for byte-exact output.
 *
 * CPython reference: Objects/unicodeobject.c, `unicode_repr()`.
 */

/**
 * A character is *not* printable when its Unicode general category is one of
 * the Other (Cc, Cf, Cs, Co, Cn) or Separator (Zl, Zp, Zs) categories.
 * ASCII space is the single exception -- Python treats U+0020 as printable.
 *
 * CPython reference: Objects/unicodectype.c, `_PyUnicode_IsPrintable()`.
 */
const NONPRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/** Python's `str.isprintable()` for a single character. */
export function isPrintable(ch) {
  return ch === ' ' || !NONPRINTABLE.test(ch);
}

/** `\xNN`, `\uXXXX` or `\UXXXXXXXX`, whichever is the shortest that fits. */
function escapeCodePoint(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * `repr(s)` for a Python `str`.
 *
 * Single quotes are preferred; Python switches to double quotes only when the
 * string contains a single quote *and* no double quote, which is why
 * `repr("x''y")` is `"x''y"` but `repr(`a'b"c`)` is `'a\'b"c'`.
 */
export function reprStr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    if (ch === quote || ch === '\\') {
      out += '\\' + ch;
      continue;
    }
    if (ch === '\t') { out += '\\t'; continue; }
    if (ch === '\n') { out += '\\n'; continue; }
    if (ch === '\r') { out += '\\r'; continue; }

    const cp = ch.codePointAt(0);
    if (cp < 0x20 || cp === 0x7f) { out += escapeCodePoint(cp); continue; }
    if (cp < 0x7f) { out += ch; continue; }
    out += isPrintable(ch) ? ch : escapeCodePoint(cp);
  }
  return out + quote;
}

