/**
 * lib/python/types.mjs
 *
 * A minimal model of the Python values `json.loads` can produce.
 *
 * JavaScript cannot tell `1` from `1.0`, but the program's observable output
 * can: a schema of `1` fails with `argument of type 'int' is not iterable`
 * while `1.0` reports `'float'`.  Numbers are therefore boxed, and `int` keeps
 * arbitrary precision via BigInt just as Python does.
 *
 * Strings and booleans map directly onto their JavaScript counterparts, so only
 * None/int/float/list/dict need wrappers.
 */

/** Python's `None` singleton. */
export const PyNone = Object.freeze({ __pyNone__: true });

/** An arbitrary-precision Python `int`. */
export class PyInt {
  constructor(value) {
    this.value = value; // BigInt
  }
}

/** A Python `float` (IEEE-754 double, may be NaN or +/-Infinity). */
export class PyFloat {
  constructor(value) {
    this.value = value; // number
  }
}

/** A Python `list`. */
export class PyList {
  constructor(items = []) {
    this.items = items;
  }
}

/**
 * A Python `dict` with string keys.  A Map preserves insertion order and gives
 * last-wins semantics for duplicate JSON keys, matching CPython.
 */
export class PyDict {
  constructor(pairs = []) {
    this.map = new Map();
    for (const [key, value] of pairs) this.map.set(key, value);
  }

  /** `key in self` */
  has(key) {
    return this.map.has(key);
  }

  /** `self.get(key)` -- absent keys yield `None`, not `undefined`. */
  get(key, fallback = PyNone) {
    return this.map.has(key) ? this.map.get(key) : fallback;
  }

  /** `self.items()` */
  items() {
    return [...this.map.entries()];
  }
}

/** `type(value).__name__` */
export function typeName(value) {
  if (value === PyNone) return 'NoneType';
  if (typeof value === 'boolean') return 'bool';
  if (typeof value === 'string') return 'str';
  if (value instanceof PyInt) return 'int';
  if (value instanceof PyFloat) return 'float';
  if (value instanceof PyList) return 'list';
  if (value instanceof PyDict) return 'dict';
  return 'object';
}

/**
 * Whether `needle in value` is legal, i.e. whether the value implements
 * `__contains__` / `__iter__`.  Scalars do not, and raise TypeError.
 */
export function supportsContains(value) {
  return typeof value === 'string' || value instanceof PyList || value instanceof PyDict;
}

/**
 * Python's `needle in container` for a string needle.  Note the three very
 * different meanings: substring search on `str`, element equality on `list`,
 * key lookup on `dict`.  This distinction is load-bearing -- it is why a schema
 * of `"xx$refyy"` takes a different code path than `"xx"`.
 */
export function contains(container, needle) {
  if (typeof container === 'string') return container.includes(needle);
  if (container instanceof PyList) {
    return container.items.some((item) => typeof item === 'string' && item === needle);
  }
  if (container instanceof PyDict) return container.has(needle);
  return false;
}

