/**
 * lib/python/json/decoder.mjs
 *
 * A port of CPython's JSON scanner, faithful down to the error positions.
 *
 * Two details drive the design:
 *
 *  1. CPython uses the C accelerator (`_json`), whose messages differ from the
 *     pure-Python fallback -- it reports `Invalid control character at` with no
 *     repr of the offending character, and it lets a failed value match escape
 *     as `StopIteration` from *any* nesting depth, so nested `Expecting value`
 *     errors surface from `raw_decode` rather than from `JSONObject`.
 *
 *  2. Positions are counted in **code points**, not UTF-16 units.  `["\u{1F600}",]`
 *     reports char 5, which JavaScript string indices would report as 6.  The
 *     document is therefore scanned as an array of code points.
 */

import {
  PyException,
  PyFrame,
  callInFrame,
} from '../exceptions.mjs';
import { PyNone, PyInt, PyFloat, PyList, PyDict } from '../types.mjs';

/** The scanner's whitespace set -- note `\f` and `\v` are *not* included. */
const WHITESPACE = new Set([' ', '\t', '\n', '\r']);

/** Recognised two-character escapes, `\uXXXX` excluded. */
const BACKSLASH = new Map([
  ['"', '"'],
  ['\\', '\\'],
  ['/', '/'],
  ['b', '\b'],
  ['f', '\f'],
  ['n', '\n'],
  ['r', '\r'],
  ['t', '\t'],
]);

/** Frames inside the frozen `json` package, as the traceback names them. */
const FRAME_LOADS = new PyFrame('json/__init__.py', 346, 'loads');
const FRAME_DECODE_CALL = new PyFrame('json/decoder.py', 337, 'decode');
const FRAME_DECODE_EXTRA_DATA = new PyFrame('json/decoder.py', 340, 'decode');
const FRAME_RAW_DECODE_SCAN = new PyFrame('json/decoder.py', 353, 'raw_decode');
const FRAME_RAW_DECODE_VALUE = new PyFrame('json/decoder.py', 355, 'raw_decode');

/**
 * Signals "no value could be matched here".  The C scanner raises
 * `StopIteration(idx)`, which propagates through nested containers up to
 * `raw_decode`, where it becomes `Expecting value`.
 */
class StopIteration extends Error {
  constructor(value) {
    super('StopIteration');
    this.value = value;
  }
}

/** `1 + doc.count('\n', 0, pos)` and `pos - doc.rfind('\n', 0, pos)`. */
function lineAndColumn(doc, pos) {
  let newlines = 0;
  let lastNewline = -1;
  const limit = Math.min(pos, doc.length);
  for (let i = 0; i < limit; i++) {
    if (doc[i] === '\n') {
      newlines += 1;
      lastNewline = i;
    }
  }
  return [newlines + 1, pos - lastNewline];
}

export class JSONDecodeError extends PyException {
  /**
   * @param {string} msg reason, without position
   * @param {string[]} doc document as code points
   * @param {number} pos code-point offset of the offending character
   */
  constructor(msg, doc, pos) {
    const [lineno, colno] = lineAndColumn(doc, pos);
    super('json.decoder.JSONDecodeError', `${msg}: line ${lineno} column ${colno} (char ${pos})`);
    this.msg = msg;
    this.pos = pos;
    this.lineno = lineno;
    this.colno = colno;
  }
}

function isDigit(ch) {
  return ch !== undefined && ch >= '0' && ch <= '9';
}

function isHexDigit(ch) {
  return ch !== undefined && /^[0-9a-fA-F]$/.test(ch);
}

/**
 * The recursive-descent scanner, equivalent to `_json.make_scanner`'s
 * `scan_once` and its `_parse_object` / `_parse_array` / `scanstring` helpers.
 */
export class Scanner {
  /** @param {string[]} doc document as an array of code points */
