 *
 * The `json` package's public surface -- just `loads`, which is all the program
 * uses.  Mirrors `json/__init__.py`, whose frame appears in every decode
 * traceback.
 */

import { callInFrame } from '../exceptions.mjs';
import { JSONDecoder, FRAME_LOADS } from './decoder.mjs';

/**
 * `json.loads(s)`
 *
 * The input is expanded to an array of code points up front so that every
 * position the scanner reports is a Python-style character offset.
 */
export function loads(text) {
  const doc = Array.from(text);
  return callInFrame(FRAME_LOADS, () => new JSONDecoder().decode(doc));
}

