/**
 * lib/jsonschema/validators.mjs
 *
 * `Draft7Validator`, reduced to what constructing one actually does.
 *
 * `jsonschema` builds its validator classes with `attrs`, so the traceback for a
 * failing constructor shows a synthesised `__init__` frame before
 * `__attrs_post_init__`.  That post-init step does exactly two things that can
 * observe the schema:
 *
 *   validators.py:289  build the reference resolver, reading the schema's `$id`
 *   validators.py:296  expand the applicable validators via ignore_ref_siblings
 *
 * The second step is skipped for boolean schemas, which is why `--a true`
 * succeeds even though `True.get` would not.  Nested subschemas are never
 * inspected, and the schema is never checked against its meta-schema.
 */

import { PyFrame, callInFrame } from '../python/exceptions.mjs';
import { resolverWithRoot } from '../referencing/core.mjs';
import { ignoreRefSiblings } from './legacyKeywords.mjs';
import { draft7TypeChecker } from './types.mjs';

const FRAME_ATTRS_INIT = new PyFrame(
  '<attrs generated methods jsonschema.validators.create.<locals>.Validator>',
  32,
  '__init__',
);
const FRAME_POST_INIT_RESOLVER = new PyFrame('jsonschema/validators.py', 289, '__attrs_post_init__');
const FRAME_POST_INIT_VALIDATORS = new PyFrame('jsonschema/validators.py', 296, '__attrs_post_init__');

export class Draft7Validator {
  static TYPE_CHECKER = draft7TypeChecker;

  constructor(schema) {
    this.schema = schema;
    this.TYPE_CHECKER = draft7TypeChecker;

    callInFrame(FRAME_ATTRS_INIT, () => {
      callInFrame(FRAME_POST_INIT_RESOLVER, () => resolverWithRoot(schema));
      if (typeof schema !== 'boolean') {
        callInFrame(FRAME_POST_INIT_VALIDATORS, () => ignoreRefSiblings(schema));
      }
    });
  }
}

