/**
 * test8.mjs -- Node.js port of test8.py
 *
 *     import argparse
 *     import json
 *     import jsonschema
 *     from jsonschema import Draft7Validator
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--a', type=str, required=True, help='schema (JSON string)')
 *     parser.add_argument('--b', type=str, required=True, help='type name')
 *     args = parser.parse_args()
 *
 *     schema = json.loads(args.a)
 *
 *     validator = Draft7Validator(schema)  # Create validator
 *     type_checker = validator.TYPE_CHECKER  # Get type checker
 *     result = type_checker.is_type(args.b, args.b)  # Check if type exists
 *     print(result)
 *
 * `is_type(args.b, args.b)` asks whether the *string* `--b` is an instance of
 * the JSON type named by `--b`, so only `string` is ever True; the other six
 * draft-7 types are False, and anything else is an unhandled UndefinedTypeCheck.
 *
 * Failures are reported as Python tracebacks on stderr with exit status 1, and
 * argparse failures as usage text with exit status 2, matching the original.
 * (The reference build is frozen with PyInstaller, whose bootloader appends a
 * `[PYI-<pid>:ERROR] Failed to execute script ...` line after the traceback.
 * That line comes from the bootloader rather than from Python, and its pid
 * varies per run, so it is deliberately not reproduced.)
 */

import process from 'node:process';

import { ArgumentParser } from './lib/python/argparse.mjs';
import { loads } from './lib/python/json/api.mjs';
import { Draft7Validator } from './lib/jsonschema/index.mjs';
import { PyException, PySystemExit, PyFrame, callInFrame } from './lib/python/exceptions.mjs';
import { formatTraceback } from './lib/python/traceback.mjs';

/**
 * The three statements that can raise, as the traceback names them.  Each holds
 * the source line plus the span the `^^^` run underlines.
 */
const AT_JSON_LOADS = new PyFrame(
  'test8.py',
  11,
  '<module>',
  'schema = json.loads(args.a)',
  'schema = '.length,
  'json.loads(args.a)'.length,
);
const AT_VALIDATOR = new PyFrame(
  'test8.py',
  13,
  '<module>',
  'validator = Draft7Validator(schema)  # Create validator',
  'validator = '.length,
  'Draft7Validator(schema)'.length,
);
const AT_IS_TYPE = new PyFrame(
  'test8.py',
  15,
  '<module>',
  'result = type_checker.is_type(args.b, args.b)  # Check if type exists',
  'result = '.length,
  'type_checker.is_type(args.b, args.b)'.length,
);

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { required: true, help: 'schema (JSON string)' });
  parser.addArgument('--b', { required: true, help: 'type name' });
  const args = parser.parseArgs(process.argv.slice(2));

  const schema = callInFrame(AT_JSON_LOADS, () => loads(args.a));

  const validator = callInFrame(AT_VALIDATOR, () => new Draft7Validator(schema));
  const typeChecker = validator.TYPE_CHECKER;
  const result = callInFrame(AT_IS_TYPE, () => typeChecker.isType(args.b, args.b));

  // print(result) -- Python renders bools as True/False.
  process.stdout.write(`${result ? 'True' : 'False'}\n`);
}

try {
  main();
} catch (error) {
  if (error instanceof PySystemExit) {
    process.exitCode = error.code;
  } else if (error instanceof PyException) {
    process.stderr.write(formatTraceback(error));
    process.exitCode = 1;
  } else {
    throw error;
  }
}

