 * and byte-compares stdout / stderr / exit code.
 *
 * Two normalisations are applied to the reference's stderr, both for artefacts
 * that are not part of the Python program's output:
 *   - the PyInstaller bootloader's `[PYI-<pid>:ERROR] ...` line is dropped
 *   - the argparse program name (argv[0] basename) is unified
 *
 * Usage:
 *   node diff.mjs                 # run the built-in suite
 *   node diff.mjs --cases f.json  # run cases from a JSON array of argv arrays
 *   node diff.mjs -- --a '{}' --b string    # a single ad-hoc case
 */
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import process from 'node:process';

const PY = '/workspace/dataset/test8_executable';
const JS = '/output/test8.mjs';

function normalize(text, prog) {
  return text
    .split('\n')
    .filter((line) => !/^\[PYI-\d+:ERROR\]/.test(line))
    .join('\n')
    .split(`usage: ${prog} `)
    .join('usage: PROG ')
    .split(`${prog}: error: `)
    .join('PROG: error: ');
}

export function runCase(argv) {
  const py = spawnSync(PY, argv, { encoding: 'utf8', maxBuffer: 1 << 28 });
  const js = spawnSync(process.execPath, [JS, ...argv], { encoding: 'utf8', maxBuffer: 1 << 28 });

  const expected = {
    stdout: py.stdout ?? '',
    stderr: normalize(py.stderr ?? '', 'test8_executable'),
    status: py.status,
  };
  const actual = {
    stdout: js.stdout ?? '',
    stderr: normalize(js.stderr ?? '', 'test8.mjs'),
    status: js.status,
  };

  const problems = [];
  if (expected.stdout !== actual.stdout) problems.push('stdout');
  if (expected.stderr !== actual.stderr) problems.push('stderr');
  if (expected.status !== actual.status) problems.push('exit');
  return { argv, expected, actual, problems };
