/**
 * lib/python/linecache.mjs
 *
 * `linecache.getline`, the reason traceback source lines come and go.
 *
 * A traceback records only a file *name*; CPython recovers the text by opening
 * that name at render time.  For a frozen build the name `test8.py` is relative,
 * so it resolves against the current working directory -- run the reference from
 * a directory holding a `test8.py` and its tracebacks gain source and caret
 * lines, run it from anywhere else and they do not.
 */

import { readFileSync } from 'node:fs';

const cache = new Map();

/** Read and split a file the way Python's universal-newline text mode does. */
function getlines(filename) {
  if (cache.has(filename)) return cache.get(filename);

  let lines = null;
  try {
    const text = readFileSync(filename, 'utf8');
    lines = text.split(/\r\n|\r|\n/);
    // A trailing newline does not start a further line.
    if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
  } catch {
    lines = null; // unreadable, a directory, missing: Python yields no lines
  }
  cache.set(filename, lines);
  return lines;
}

/**
 * `linecache.getline(filename, lineno)` without the trailing newline.
 * @returns {?string} null when the file or the line is unavailable
 */
export function getline(filename, lineno) {
  const lines = getlines(filename);
  if (lines === null) return null;
  if (lineno < 1 || lineno > lines.length) return null;
  return lines[lineno - 1];
}

