/**
 * lib/python/exceptions.mjs
 *
 * Python exception objects plus the traceback bookkeeping needed to render them
 * the way CPython does.
 *
 * A `PyException` carries its own stack of `PyFrame`s rather than relying on the
 * JavaScript stack, because the frames we must print name *Python* source
 * locations inside the frozen `json`, `jsonschema` and `referencing` packages.
 * Frames are stored outermost-first (print order) and each caller prepends its
 * own frame as the exception propagates, exactly as CPython builds `__traceback__`.
 */

/** One line (or three, with source and carets) of a rendered traceback. */
export class PyFrame {
  /**
   * @param {string} file    as it appears after `File "`
   * @param {number} line    line number
   * @param {string} name    function name, e.g. `<module>`
   * @param {?string} source stripped source line; omitted for frozen stdlib frames
   * @param {number} caretStart column within `source` where the `^^^` run begins
   * @param {number} caretLength length of the `^^^` run; 0 suppresses the caret line
   */
  constructor(file, line, name, source = null, caretStart = 0, caretLength = 0) {
    this.file = file;
    this.line = line;
    this.name = name;
    this.source = source;
    this.caretStart = caretStart;
    this.caretLength = caretLength;
  }
}

/** Base class for every emulated Python exception. */
export class PyException extends Error {
  /**
   * @param {string} qualifiedName as printed on the final traceback line, e.g.
   *   `TypeError` or `json.decoder.JSONDecodeError`
   * @param {string} pyMessage `str(exc)`
   */
  constructor(qualifiedName, pyMessage) {
    super(`${qualifiedName}: ${pyMessage}`);
    this.qualifiedName = qualifiedName;
    this.pyMessage = pyMessage;
    this.frames = [];
  }

  /** Record that this exception passed through `frame`. */
  atFrame(frame) {
    this.frames.unshift(frame);
    return this;
  }
}

export class PyTypeError extends PyException {
  constructor(message) {
    super('TypeError', message);
  }
}

export class PyAttributeError extends PyException {
  constructor(message) {
    super('AttributeError', message);
  }
}

/**
 * Raised by `argparse` to end the process.  Carries no traceback: CPython's
 * default excepthook treats SystemExit specially and prints nothing.
 */
export class PySystemExit extends PyException {
  constructor(code) {
    super('SystemExit', String(code));
    this.code = code;
  }
}

/** `x in <scalar>` */
export function typeErrorNotIterable(type) {
  return new PyTypeError(`argument of type '${type}' is not iterable`);
}

/** `<value>.attr` where the type has no such attribute */
export function attributeErrorMissing(type, attribute) {
  return new PyAttributeError(`'${type}' object has no attribute '${attribute}'`);
}

/**
 * Run `fn`, tagging any Python exception that escapes with `frame`.
 *
 * This is the emulation's equivalent of a Python call: the callee has already
 * pushed the frames below `frame`, so prepending here yields the same
 * innermost-last ordering CPython prints.
 */
export function callInFrame(frame, fn) {
  try {
    return fn();
  } catch (error) {
    if (error instanceof PyException) error.atFrame(frame);
    throw error;
  }
}

