/**
 * lib/python/traceback.mjs
 *
 * Renders a `PyException` the way CPython's default excepthook does:
 *
 *     Traceback (most recent call last):
 *       File "test8.py", line 15, in <module>
 *         result = type_checker.is_type(args.b, args.b)  # Check if type exists
 *                  ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
 *       File "jsonschema/_types.py", line 114, in is_type
 *     jsonschema.exceptions.UndefinedTypeCheck: Type 'foo' is unknown ...
 *
 * The source line is not stored in the traceback; it is looked up by file name at
 * render time (see lib/python/linecache.mjs), so those two middle lines appear
 * only when the source is actually reachable.  Frames from the frozen `json`,
 * `jsonschema` and `referencing` modules never resolve and print as one line.
 */

import { Buffer } from 'node:buffer';
import { getline } from './linecache.mjs';

const SOURCE_INDENT = 4;

/**
 * `traceback._byte_offset_to_character_offset`: the column numbers stored in a
 * code object are byte offsets into the UTF-8 encoded line, so they must be
 * converted before they can be used to place carets.  Slicing past the end of
 * the line clamps, which is what keeps short lines from overflowing.
 */
function byteOffsetToCharOffset(line, byteOffset) {
  const bytes = Buffer.from(line, 'utf8');
  return Array.from(bytes.subarray(0, byteOffset).toString('utf8')).length;
}

/**
 * The `^^^` run under a source line.
 *
 * Offsets are measured against the *original* line but printed against the
 * stripped one, so the leading whitespace that was stripped is subtracted back
 * out.  CPython omits the run entirely when it would span the whole statement.
 *
 * @returns {?string} the caret line, or null if it should be suppressed
 */
function formatCarets(originalLine, strippedLine, position) {
  const start = byteOffsetToCharOffset(originalLine, position.colno);
  const end = byteOffsetToCharOffset(originalLine, position.endColno);
  if (end - start >= Array.from(strippedLine).length) return null;

  const stripped = originalLine.length - originalLine.trimStart().length;
  const indent = Math.max(0, SOURCE_INDENT + start - stripped);
  return ' '.repeat(indent) + '^'.repeat(Math.max(0, end - start));
}

export function formatTraceback(exception) {
  const lines = ['Traceback (most recent call last):'];

  for (const frame of exception.frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    if (frame.position === null) continue;

    const source = getline(frame.file, frame.line);
    if (source === null) continue;

    const stripped = source.trim();
    lines.push(' '.repeat(SOURCE_INDENT) + stripped);
    const carets = formatCarets(source, stripped, frame.position);
    if (carets !== null) lines.push(carets);
  }

  lines.push(`${exception.qualifiedName}: ${exception.pyMessage}`);
  return lines.join('\n') + '\n';
}

