 * out.  CPython omits the run entirely when it would span the whole statement.
 *
 * @returns {?string} the caret line, or null if it should be suppressed
 */
function formatCarets(originalLine, strippedLine, position) {
  const start = byteOffsetToCharOffset(originalLine, position.colno);
  const end = byteOffsetToCharOffset(originalLine, position.endColno);
  if (end - start >= Array.from(strippedLine).length) return null;

  const stripped = originalLine.length - originalLine.trimStart().length;
  const indent = Math.max(0, SOURCE_INDENT + start - stripped);
  return ' '.repeat(indent) + '^'.repeat(Math.max(0, end - start));
}

export function formatTraceback(exception) {
  const lines = ['Traceback (most recent call last):'];

  for (const frame of exception.frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    if (frame.position === null) continue;

    const source = getline(frame.file, frame.line);
    if (source === null) continue;

    const stripped = source.trim();
    lines.push(' '.repeat(SOURCE_INDENT) + stripped);
    const carets = formatCarets(source, stripped, frame.position);
    if (carets !== null) lines.push(carets);
  }

  lines.push(`${exception.qualifiedName}: ${exception.pyMessage}`);
  return lines.join('\n') + '\n';
}

