/**
 * lib/python/traceback.mjs
 *
 * Renders a `PyException` the way CPython's default excepthook does:
 *
 *     Traceback (most recent call last):
 *       File "test8.py", line 15, in <module>
 *         result = type_checker.is_type(args.b, args.b)  # Check if type exists
 *                  ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
 *       File "jsonschema/_types.py", line 114, in is_type
 *     jsonschema.exceptions.UndefinedTypeCheck: Type 'foo' is unknown ...
 *
 * Source lines are indented four spaces and the fine-grained caret run
 * (Python 3.11+) is offset relative to that indent.  Frozen library frames
 * carry no source line, so they print as a single `File "..."` line.
 */

const SOURCE_INDENT = '    ';

export function formatTraceback(exception) {
  const lines = ['Traceback (most recent call last):'];

  for (const frame of exception.frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    if (frame.source === null) continue;

    lines.push(SOURCE_INDENT + frame.source);
    if (frame.caretLength > 0) {
      lines.push(SOURCE_INDENT + ' '.repeat(frame.caretStart) + '^'.repeat(frame.caretLength));
    }
  }

  lines.push(`${exception.qualifiedName}: ${exception.pyMessage}`);
  return lines.join('\n') + '\n';
}

