/**
 * lib/python/argparse.mjs
 *
 * Enough of CPython's `argparse` to reproduce this program's command line
 * exactly: two required value-taking long options plus the automatic `-h`.
 *
 * The subtleties that are reproduced deliberately:
 *
 *  - Long options match by prefix (`--he` reaches `--help`), but the *argument*
 *    must be a prefix of the option, so `--ab` matches nothing.
 *  - A token beginning with `-` is only usable as a value when it is a negative
 *    number (`-1`, `-.5`), contains a space, or is exactly `-`.  `-1e5` and
 *    `-Infinity` are read as options and fail with `expected one argument`.
 *  - For an *optional* action, argparse strips `-*` from the nargs pattern, so
 *    the value must be the immediately following non-option token: `--a -- 1`
 *    is an error rather than `a="1"`.
 *  - The missing-required check runs before the unrecognised-arguments check.
 */

import { basename } from 'node:path';
import process from 'node:process';
import { PySystemExit } from './exceptions.mjs';

/** argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** `HelpFormatter._max_help_position` */
const MAX_HELP_POSITION = 24;

/** `os.path.basename(sys.argv[0])`, argparse's default `prog`. */
function defaultProg() {
  const script = process.argv[1];
  return script ? basename(script) : 'test8.mjs';
}

class Action {
  constructor(optionStrings, { dest, metavar, required = false, help = '', nargs = null }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.metavar = metavar;
    this.required = required;
    this.help = help;
    this.nargs = nargs; // null => exactly one value; 0 => flag
  }

  /** `HelpFormatter._format_action_invocation` */
  formatInvocation() {
    if (this.nargs === 0) return this.optionStrings.join(', ');
    return this.optionStrings.map((option) => `${option} ${this.metavar}`).join(', ');
  }

  /** How the action appears inside the `usage:` line. */
  formatUsage() {
    const head = this.nargs === 0
      ? this.optionStrings[0]
      : `${this.optionStrings[0]} ${this.metavar}`;
    return this.required ? head : `[${head}]`;
  }

  /** `_get_action_name` */
  name() {
    return this.optionStrings.join('/');
  }
}

export class ArgumentParser {
  constructor({ prog = defaultProg(), stdout = null, stderr = null } = {}) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.write = {
      out: stdout || ((text) => process.stdout.write(text)),
      err: stderr || ((text) => process.stderr.write(text)),
    };

    this.addArgument(['-h', '--help'], {
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  /** `parser.add_argument(...)` */
  addArgument(optionStrings, { action = 'store', required = false, help = '' } = {}) {
    const options = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
    // dest is taken from the first long option, dashes stripped.
    const long = options.find((option) => option.startsWith('--')) || options[0];
    const dest = long.replace(/^-+/, '').replace(/-/g, '_');

    const created = new Action(options, {
      dest,
      metavar: dest.toUpperCase(),
      required,
      help,
      nargs: action === 'help' ? 0 : null,
    });
    created.isHelp = action === 'help';

    this.actions.push(created);
    for (const option of options) this.optionStringActions.set(option, created);
    return created;
  }

  // ---------------------------------------------------------------- output

  formatUsage() {
    return `usage: ${this.prog} ${this.actions.map((a) => a.formatUsage()).join(' ')}\n`;
  }

  /**
   * `HelpFormatter.format_help` for a parser with no description, no epilog and
   * no positionals -- the help column is aligned to the longest invocation.
   */
  formatHelp() {
    const invocations = this.actions.map((action) => action.formatInvocation());
    const actionMaxLength = Math.max(...invocations.map((s) => s.length)) + 2;
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - 2 - 2;

    const lines = [this.formatUsage(), '\n', 'options:\n'];
    this.actions.forEach((action, index) => {
      const invocation = invocations[index];
      if (invocation.length <= actionWidth) {
        lines.push(`  ${invocation.padEnd(actionWidth)}  ${action.help}\n`);
      } else {
        lines.push(`  ${invocation}\n`);
        lines.push(`${' '.repeat(helpPosition)}${action.help}\n`);
      }
    });
    return lines.join('');
  }

  printHelp() {
    this.write.out(this.formatHelp());
  }

  /** `parser.error` -- usage then message on stderr, exit status 2. */
  error(message) {
    this.write.err(this.formatUsage());
    this.write.err(`${this.prog}: error: ${message}\n`);
    throw new PySystemExit(2);
  }

  // ----------------------------------------------------------------- parse

  /** `parser.parse_args` */
  parseArgs(argv) {
    const [namespace, extras] = this.parseKnownArgs(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /**
   * `parser._parse_optional`: decide whether a token is an option.
   * Returns `[action|null, optionString, explicitArg|null]`, or null for a value.
   */
  parseOptional(argString) {
    if (argString.length === 0) return null;
    if (argString[0] !== '-') return null;

    if (this.optionStringActions.has(argString)) {
      return [this.optionStringActions.get(argString), argString, null];
    }
    if (argString.length === 1) return null; // a bare "-" is a value

    if (argString.includes('=')) {
      const at = argString.indexOf('=');
      const optionString = argString.slice(0, at);
      if (this.optionStringActions.has(optionString)) {
        return [this.optionStringActions.get(optionString), optionString, argString.slice(at + 1)];
      }
    }

    const candidates = this.getOptionTuples(argString);
    if (candidates.length > 1) {
      const names = candidates.map((tuple) => tuple[1]).join(', ');
      this.error(`ambiguous option: ${argString} could match ${names}`);
    }
    if (candidates.length === 1) return candidates[0];

    // Looks like a negative number and no option does => it is a value.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    // Contains a space => it is a value.
    if (argString.includes(' ')) return null;

    return [null, argString, null]; // an unknown option
  }

  /** `parser._get_option_tuples`: abbreviation matching. */
  getOptionTuples(argString) {
    const result = [];

    if (argString.startsWith('--')) {
      let optionPrefix = argString;
      let explicitArg = null;
      if (argString.includes('=')) {
        const at = argString.indexOf('=');
        optionPrefix = argString.slice(0, at);
        explicitArg = argString.slice(at + 1);
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) result.push([action, optionString, explicitArg]);
      }
      return result;
    }

    const shortPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortPrefix) result.push([action, optionString, shortExplicitArg]);
      else if (optionString.startsWith(argString)) result.push([action, optionString, null]);
    }
    return result;
  }

  /** `parser.parse_known_args` */
  parseKnownArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (!action.isHelp) namespace[action.dest] = undefined;
    }

    // Classify every token: 'O' option, 'A' value, '-' the "--" separator.
    const pattern = [];
    const optionTuples = new Map();
    let afterSeparator = false;
    for (let i = 0; i < argv.length; i++) {
      if (!afterSeparator && argv[i] === '--') {
        pattern.push('-');
        afterSeparator = true;
        continue;
      }
      if (afterSeparator) {
        pattern.push('A');
        continue;
      }
      const tuple = this.parseOptional(argv[i]);
      if (tuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(i, tuple);
        pattern.push('O');
      }
    }

    const seen = new Set();
    const extras = [];
    let i = 0;
    while (i < argv.length) {
      if (pattern[i] !== 'O') {
        // No positionals are defined, so anything left over is unrecognised.
        extras.push(argv[i]);
        i += 1;
        continue;
      }

      const [action, optionString, explicitArg] = optionTuples.get(i);
      if (action === null) {
        extras.push(argv[i]);
        i += 1;
        continue;
      }
      if (action.isHelp) {
        this.printHelp();
        throw new PySystemExit(0);
      }
      if (explicitArg !== null) {
        namespace[action.dest] = explicitArg;
        seen.add(action);
        i += 1;
        continue;
      }
      // nargs=None on an optional: the value must be the very next value token.
      if (pattern[i + 1] !== 'A') {
        this.error(`argument ${optionString}: expected one argument`);
      }
      namespace[action.dest] = argv[i + 1];
      seen.add(action);
      i += 2;
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.name());
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }
}

