function main() {
  const argv = process.argv.slice(2);
  let cases = DEFAULT_CASES;
  const sep = argv.indexOf('--');
  if (sep === 0) {
    cases = [argv.slice(1)];
  } else if (argv[0] === '--cases') {
    cases = JSON.parse(readFileSync(argv[1], 'utf8'));
  }

  let failures = 0;
  for (const testCase of cases) {
    const result = runCase(testCase);
    if (result.problems.length === 0) continue;
    failures += 1;
    console.log(`\n=== MISMATCH (${result.problems.join(',')}) argv=${JSON.stringify(testCase)}`);
    for (const key of result.problems) {
      const field = key === 'exit' ? 'status' : key;
      console.log(`--- expected ${field}: ${JSON.stringify(result.expected[field])}`);
      console.log(`--- actual   ${field}: ${JSON.stringify(result.actual[field])}`);
    }
  }
  console.log(`\n${cases.length - failures}/${cases.length} cases match`);
  process.exitCode = failures === 0 ? 0 : 1;
}

if (process.argv[1] && process.argv[1].endsWith('diff.mjs')) main();
